--
-- Name: lesson_skill_positions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lesson_skill_positions AS
 WITH RECURSIVE unit_paths(id, path) AS (
         SELECT units.id,
            ARRAY[units.unit_sequence] AS "array"
           FROM public.units
          WHERE (units.parent_id IS NULL)
        UNION ALL
         SELECT u.id,
            (p.path || u.unit_sequence)
           FROM (public.units u
             JOIN unit_paths p ON ((u.parent_id = p.id)))
        )
 SELECT ls.skill_id,
    ls.lesson_id,
    (row_number() OVER (PARTITION BY ls.skill_id ORDER BY up.path, l.lesson_unit_sequence, l.id) - 1) AS "position"
   FROM ((public.lesson_skills ls
     JOIN public.lessons l ON ((l.id = ls.lesson_id)))
     LEFT JOIN unit_paths up ON ((up.id = l.unit_id)));


